package EnergyCommunity.core.mcpServer.tools.model;

import java.time.Instant;

/**
 * Data model representing a battery optimization proposal generated by the MCP Server.
 *
 * @param id              Unique proposal identifier
 * @param userId          Owner user identifier
 * @param houseId         Target house identifier
 * @param description     Human-readable summary of the proposed schedule
 * @param reasoning       Explanation of why the AI agent proposed this schedule
 * @param actionType      Type of battery operation
 * @param sellPercent     Percentage of battery capacity involved in the operation (0-100)
 * @param executeAt       Scheduled execution timestamp
 * @param estimatedProfit Estimated profit or savings in EUR
 * @param status          Current lifecycle status (PENDING, ACCEPTED, REJECTED, EXPIRED)
 * @param createdAt       Timestamp when the proposal was created
 */
public record BatteryProposal(
        String id,
        String userId,
        String houseId,
        String description,
        String reasoning,
        BatteryActionType actionType,
        int sellPercent,
        Instant executeAt,
        Double estimatedProfit,
        ProposalStatus status,
        Instant createdAt
) {
}
